message.content:
{
  "description": "The creature is shown in right-facing profile against a plain off-white background, standing on all four legs. It has the overall body shape of a slender equid with a long neck, narrow torso, and long legs. Its coat is coarse and shaggy, predominantly brownish-gray with a lighter, off-white underbelly and muzzle, a short upright bristly mane along the neck, a thin hanging tail with a dark tuft at the tip, and faint irregular dark striping across the torso, hindquarters, shoulders, neck and lower legs, plus a dark dorsal stripe along the back and a dark vertical stripe over the shoulder.",
  "parts": [
    {
      "part": "head",
      "looks_like": "elongated equid head at the front of the neck, facing right, with brown fur on the forehead and cheeks, a white muzzle around the nose and mouth, a visible dark nostril, a dark eye with a pale ring around it, and short whiskers on the lower lip",
      "where": "at the anterior end of the neck, highest point of the front of the body"
    },
    {
      "part": "ears",
      "looks_like": "two large, upright, pointed ears with dark outer edges and lighter inner fur, the inner surface showing dark markings",
      "where": "on top of the head, one slightly behind the other in profile view"
    },
    {
      "part": "mane",
      "looks_like": "short, stiff, upright tufted hair forming a bristly crest, dark brown to black with lighter tips giving a striped appearance",
      "where": "along the dorsal midline of the neck from just behind the ears to the top of the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four long, slender legs with light tan to off-white fur on the lower portions and faint dark horizontal striping, the two forelegs straight under the chest and the two hindlegs slightly angled under the rump",
      "where": "two forelegs beneath the chest at the front of the body and two hindlegs beneath the hindquarters at the rear"
    },
    {
      "part": "feet",
      "looks_like": "four single-toed hooves, dark gray-brown, rounded and slightly flared at the base, with a small tuft of hair at the fetlock above each hoof",
      "where": "at the distal tip of each leg, contacting the ground line"
    },
    {
      "part": "tail",
      "looks_like": "thin, medium-length tail with short hair along its length and a longer, darker tuft of hair at the tip, hanging straight down",
      "where": "extending from the rear of the rump at the back of the body"
    },
    {
      "part": "markings",
      "looks_like": "irregular faint dark brown to black stripes of varying width and length across the torso, hindquarters, shoulders, neck and lower legs, plus a solid dark dorsal stripe running along the spine and a solid dark vertical shoulder stripe; the stripes are most distinct on the hindquarters and lower legs and more diffuse on the mid-body",
      "where": "distributed over the sides of the body, hindquarters, shoulders, neck, and encircling the lower legs, with the dorsal stripe on the mid-back and the shoulder stripe just behind the neck"
    }
  ],
  "attached_objects": [],
  "animals": [
    "donkey",
    "zebra"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
